mapper.select:
SELECT COUNT(1)
FROM adm_user_mst
WHERE login_id = #{loginId}

    AND user_seq != #{excludeUserSeq}

mapper.insert:

    SELECT nextval('adm_user_mst_seq')

INSERT INTO adm_user_mst (
    user_seq, login_id, user_nm, pwd_hash, use_yn, login_fail_cnt,
    lock_yn, pwd_reset_yn, lock_until_at, created_at, created_by, updated_at, updated_by
) VALUES (
    #{user_seq}, #{login_id}, #{user_nm}, #{user_pw}, COALESCE(#{use_yn}, 'Y'),
    COALESCE(#{login_fail_cnt}, 0), COALESCE(#{lock_yn}, 'N'), COALESCE(#{pwd_reset_yn}, 'N'),
    NULL, CURRENT_TIMESTAMP, #{created_by}, CURRENT_TIMESTAMP, #{updated_by}
)

mapper.update:
UPDATE adm_user_mst
   SET use_yn = 'N',
       updated_at = CURRENT_TIMESTAMP,
       updated_by = #{updated_by}
 WHERE user_seq = #{user_seq}

UPDATE adm_user_mst
   SET user_nm = #{user_nm},
       updated_at = CURRENT_TIMESTAMP,
       updated_by = #{updated_by}
 WHERE login_id = #{login_id}
   AND COALESCE(use_yn, 'Y') = 'Y'
